// The consumer: messages in, batches out. Each batch is one R2 object under
// `{tenant}/{date}/{hour}/{stream}/`, and the object is NAMED by the id range it
// holds, `{minTs}-{maxTs}-{batch}.ndjson`. That name is the hour's manifest
// entry, written atomically with the batch, so two consumers draining the same
// hour never race on a shared manifest file. A point lookup lists the hour and
// opens the one or two objects whose range contains the id's time.
//
// R2 and Analytics Engine are two destinations, not one reading the other. This
// file writes R2; the producer wrote the points.

import { fromTs36, hourPrefix, parseId, ts36, type LedgerMessage, type LedgerWireMessage } from './records';
import type { DecisionRecord } from '@/content/types';
import type { OutcomeRecord } from './records';

export interface R2Like {
  put(key: string, body: string): Promise<unknown>;
  get(key: string): Promise<{ text(): Promise<string> } | null>;
  list(opts: { prefix: string; cursor?: string; limit?: number }): Promise<{ objects: Array<{ key: string }>; truncated: boolean; cursor?: string }>;
}

export interface WrittenBatch { key: string; count: number; stream: 'decision' | 'outcome'; prefix: string }

const streamOf = (m: LedgerMessage) => m.type;
const idOf = (m: LedgerMessage) => (m.type === 'decision' ? m.record.decision_id : m.record.outcome_id);

/** Is this a ledger message with a record we can place? Anything else is dropped, and counted by the caller. */
export function isLedgerMessage(body: unknown): body is LedgerMessage {
  if (!body || typeof body !== 'object') return false;
  const m = body as { kind?: unknown; type?: unknown; record?: unknown };
  if (m.kind !== 'ledger' || (m.type !== 'decision' && m.type !== 'outcome') || !m.record || typeof m.record !== 'object') return false;
  const id = idOf(m as LedgerMessage);
  return typeof id === 'string' && parseId(id) !== null;
}
/** A message carrying a whole decision set (doc 31), or a single record: either way, the records it holds, each placeable. */
export function expandLedgerMessage(body: unknown): LedgerMessage[] {
  if (isLedgerMessage(body)) return [body];
  if (!body || typeof body !== 'object') return [];
  const m = body as { kind?: unknown; type?: unknown; records?: unknown };
  if (m.kind !== 'ledger' || m.type !== 'decisions' || !Array.isArray(m.records)) return [];
  return (m.records as unknown[]).map((record) => ({ kind: 'ledger' as const, type: 'decision' as const, record: record as DecisionRecord })).filter((x) => isLedgerMessage(x));
}
export type { LedgerWireMessage };

/** Group messages by stream and hour, write one object per group, return what was written. */
export async function writeBatches(r2: R2Like, messages: readonly LedgerMessage[], batchId: string): Promise<WrittenBatch[]> {
  const groups = new Map<string, { prefix: string; stream: 'decision' | 'outcome'; rows: LedgerMessage[]; min: number; max: number }>();
  for (const m of messages) {
    const id = parseId(idOf(m));
    if (!id) continue;
    const prefix = hourPrefix(id.tenant, id.ts);
    const stream = streamOf(m);
    const k = `${prefix}/${stream}`;
    const g = groups.get(k) ?? { prefix, stream, rows: [], min: Infinity, max: -Infinity };
    g.rows.push(m); g.min = Math.min(g.min, id.ts); g.max = Math.max(g.max, id.ts);
    groups.set(k, g);
  }
  const written: WrittenBatch[] = [];
  for (const g of groups.values()) {
    const key = `${g.prefix}/${g.stream}/${ts36(g.min)}-${ts36(g.max)}-${batchId}.ndjson`;
    const body = g.rows.map((m) => JSON.stringify(m.record)).join('\n') + '\n';
    await r2.put(key, body);
    written.push({ key, count: g.rows.length, stream: g.stream, prefix: g.prefix });
  }
  return written;
}

/** The objects under an hour whose id range could contain `ts`. */
export async function candidateKeys(r2: R2Like, tenant: string, ts: number, stream: 'decision' | 'outcome'): Promise<string[]> {
  const prefix = `${hourPrefix(tenant, ts)}/${stream}/`;
  const out: string[] = [];
  let cursor: string | undefined;
  do {
    const page = await r2.list({ prefix, cursor, limit: 1000 });
    for (const o of page.objects) {
      const name = o.key.slice(prefix.length);
      const m = /^([0-9a-z]{9})-([0-9a-z]{9})-/.exec(name);
      if (!m) continue;
      if (fromTs36(m[1]!) <= ts && ts <= fromTs36(m[2]!)) out.push(o.key);
    }
    cursor = page.truncated ? page.cursor : undefined;
  } while (cursor);
  return out;
}

/** One decision or outcome by id: parse the id, list the hour, open the candidates. No index anywhere. */
export async function findById<T extends DecisionRecord | OutcomeRecord>(r2: R2Like, id: string, stream: 'decision' | 'outcome'): Promise<{ record: T; key: string } | null> {
  const parsed = parseId(id);
  if (!parsed) return null;
  const field = stream === 'decision' ? 'decision_id' : 'outcome_id';
  for (const key of await candidateKeys(r2, parsed.tenant, parsed.ts, stream)) {
    const obj = await r2.get(key);
    if (!obj) continue;
    for (const line of (await obj.text()).split('\n')) {
      if (!line) continue;
      try {
        const rec = JSON.parse(line) as Record<string, unknown>;
        if (rec[field] === id) return { record: rec as unknown as T, key };
      } catch { /* a bad line never hides the good ones */ }
    }
  }
  return null;
}
"},{"path":"src/ledger/erasure.test.ts","sha256":"598c26e9fa68e4d529621f6bd6270507fd6cd96c2b7b99ca1478826baff93217","contents":"// src/ledger/erasure.test.ts
// CW28 (doc 22 §15): a tombstone hides a visitor's rows at once, the rewrite
// removes them from the batch objects newest day first over the retention
// window, retires the tombstone with a hash and no id, resumes past its cap,
// and never touches another visitor or a row from after the erasure.

import { describe, it, expect, vi } from 'vitest';
import { writeBatches } from './writer';
import { ts36, type LedgerMessage } from './records';
import { dayOf, eraseVisitorLedger, resetVisitorRing, hidden, loadTombstones, pendingPrefix, retiredPrefix, rewriteErasures, tombstoneKey, withoutErased, writeTombstone } from './erasure';
import type { DecisionRecord } from '@/content/types';

class FakeR2 {
  store = new Map<string, string>(); puts = 0; deletes = 0;
  async put(key: string, body: string) { this.puts++; this.store.set(key, body); }
  async get(key: string) { const b = this.store.get(key); return b === undefined ? null : { text: async () => b }; }
  async delete(key: string) { this.deletes++; this.store.delete(key); }
  async list(opts: { prefix: string }) { return { objects: [...this.store.keys()].filter((k) => k.startsWith(opts.prefix)).sort().map((key) => ({ key })), truncated: false }; }
  keys(prefix: string) { return [...this.store.keys()].filter((k) => k.startsWith(prefix)).sort(); }
  rows(prefix: string) { return this.keys(prefix).flatMap((k) => this.store.get(k)!.split('\n').filter(Boolean).map((l) => JSON.parse(l) as { visitor_id: string; ts: number })); }
}

const DAY = 86_400_000;
const D = Date.UTC(2026, 10, 27, 14, 0, 0);          // 2026-11-27 14:00, the erasure day
const dec = (visitor: string, ts: number, n = 0): LedgerMessage => ({
  kind: 'ledger', type: 'decision',
  record: { decision_id: `coach:${ts36(ts)}:${visitor}:home:hero:${n}`, tenant: 'coach', brand: 'coach', visitor_id: visitor, ts, page: 'home', slot: 'hero', item_id: 'a' } as unknown as DecisionRecord,
});
const out = (visitor: string, ts: number): LedgerMessage => ({
  kind: 'ledger', type: 'outcome',
  record: { outcome_id: `coach:${ts36(ts)}:${visitor}:click`, tenant: 'coach', brand: 'coach', visitor_id: visitor, ts, type: 'click', event: 'click', item_id: 'a', slot: 'hero', value: null, currency: null, margin: null, products: null, session_id: null, arm: null },
});

/**
 * Two days of ledger. Objects are per stream and hour, so: 11-26 14h decisions hold only v1 (will empty);
 * 11-26 15h decisions are mixed (rewritten) and its outcomes hold only v1 (will empty); 11-27 13h decisions
 * are mixed (rewritten); 11-27 14h holds v1's one row from after the erasure (untouched).
 */
async function seed(r2: FakeR2) {
  const before = D - DAY;
  await writeBatches(r2, [dec('v1', before + 1000), dec('v1', before + 2000, 1)], 'b1');
