// src/ledger/erasure.ts
// Doc 22 §15, CW28: erasure across the ledger. The ledger is append-only and
// its R2 partition is the warehouse's export, so "delete this visitor's rows"
// is two things with one list between them.
//
// A TOMBSTONE per visitor, written the moment erasure is requested, that every
// reader honours at once: the day report, the point lookup, the replay and the
// export listing all drop a row whose visitor is tombstoned and whose time is
// at or before the erasure. And a scheduled REWRITE that walks the tenant's
// partition newest day first over the retention window, removes those rows
// from the batch objects, deletes an object that empties, and retires the
// tombstone with its counts and no visitor id. A run is capped, resumes where
// it stopped, and is idempotent: a day done twice removes nothing the second
// time. Aggregates are untouched, because counts are not personal data.
//
// The rows a visitor produces AFTER the erasure are new evidence, kept: an
// erasure is a point in time, not a ban. The retention window is the ledger's
// own (the bucket's lifecycle rule must match it) and is the number Tapestry's
// privacy team agrees; the default is the design's 90 days.

import type { Env } from '@/types/env';

export interface Tombstone {
  tenant: string;
  visitor_id: string;
  /** When erasure was requested. Rows at or before it are hidden, then removed. */
  erased_at: number;
  actor: string;
  /** The oldest day (UTC, YYYY-MM-DD) the rewrite has already cleaned for this visitor; absent before the first pass. */
  done_through?: string;
  rows_removed: number;
  objects_rewritten: number;
  objects_deleted: number;
}

/** What remains after the rewrite: the audit of an erasure, with the visitor id replaced by a hash. */
export interface RetiredTombstone {
  tenant: string;
  visitor_hash: string;
  erased_at: number;
  rewritten_at: number;
  window_days: number;
  rows_removed: number;
  objects_rewritten: number;
  objects_deleted: number;
}

export interface R2Erasable {
  put(key: string, body: string, opts?: unknown): Promise<unknown>;
  get(key: string): Promise<{ text(): Promise<string> } | null>;
  delete(key: string): Promise<unknown>;
  list(opts: { prefix: string; cursor?: string; limit?: number }): Promise<{ objects: Array<{ key: string }>; truncated: boolean; cursor?: string }>;
}
export type R2Readable = Pick<R2Erasable, 'get' | 'list'>;

export const DEFAULT_RETENTION_DAYS = 90;
const DAY = 86_400_000;

export const pendingPrefix = (tenant: string) => `erasures/${tenant}/pending/`;
export const retiredPrefix = (tenant: string) => `erasures/${tenant}/retired/`;
export const tombstoneKey = (tenant: string, visitorId: string) => `${pendingPrefix(tenant)}${encodeURIComponent(visitorId)}.json`;

export const dayOf = (ms: number): string => new Date(ms).toISOString().slice(0, 10);
const msOfDay = (day: string): number => Date.UTC(+day.slice(0, 4), +day.slice(5, 7) - 1, +day.slice(8, 10));
const prevDay = (day: string): string => dayOf(msOfDay(day) - DAY);

/** FNV-1a over the id, with its length: enough to tell audit rows apart, and no way back to the id. */
export function visitorHash(id: string): string {
  let h = 0x811c9dc5;
  for (let i = 0; i < id.length; i++) { h ^= id.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; }
  return `${h.toString(16).padStart(8, '0')}-${id.length}`;
}

/** The retention window in days: `LEDGER_RETENTION_DAYS`, or the design's default. */
export function retentionDays(env: Pick<Env, 'LEDGER_RETENTION_DAYS'>): number {
  const n = Number(env.LEDGER_RETENTION_DAYS);
  return Number.isFinite(n) && n >= 1 ? Math.floor(n) : DEFAULT_RETENTION_DAYS;
}

export async function listKeys(r2: R2Readable, prefix: string): Promise<string[]> {
  const out: string[] = [];
  let cursor: string | undefined;
  do {
    const page = await r2.list({ prefix, cursor, limit: 1000 });
    for (const o of page.objects) out.push(o.key);
    cursor = page.truncated ? page.cursor : undefined;
  } while (cursor);
  return out.sort();
}

/** Every pending tombstone for the tenant, by visitor id. */
export async function loadTombstones(r2: R2Readable, tenant: string): Promise<Map<string, Tombstone>> {
  const out = new Map<string, Tombstone>();
  for (const key of await listKeys(r2, pendingPrefix(tenant))) {
    const obj = await r2.get(key);
    if (!obj) continue;
    try {
      const t = JSON.parse(await obj.text()) as Tombstone;
      if (t && typeof t.visitor_id === 'string' && typeof t.erased_at === 'number') out.set(t.visitor_id, t);
    } catch { /* an unreadable tombstone hides nothing; the rewrite reports it */ }
  }
  return out;
}

/** Is this row hidden: its visitor is tombstoned and it happened at or before the erasure. */
export function hidden(tombs: ReadonlyMap<string, Pick<Tombstone, 'erased_at'>>, rec: { visitor_id: string; ts: number }): boolean {
  const t = tombs.get(rec.visitor_id);
  return t !== undefined && rec.ts <= t.erased_at;
}

export function withoutErased<T extends { visitor_id: string; ts: number }>(records: readonly T[], tombs: ReadonlyMap<string, Pick<Tombstone, 'erased_at'>>): T[] {
  return tombs.size ? records.filter((r) => !hidden(tombs, r)) : [...records];
}

/** Same-cutoff retries preserve progress; a genuinely later erasure restarts the window. */
export async function writeTombstone(r2: R2Erasable, tenant: string, visitorId: string, actor: string, now = Date.now()): Promise<{ key: string; tombstone: Tombstone }> {
  const key = tombstoneKey(tenant, visitorId);
  let prior: Tombstone | null = null;
  const obj = await r2.get(key);
  if (obj) {
    prior = JSON.parse(await obj.text()) as Tombstone;
    if (!prior || prior.tenant !== tenant || prior.visitor_id !== visitorId || !Number.isSafeInteger(prior.erased_at) || prior.erased_at < 0
      || typeof prior.actor !== 'string' || prior.actor.length < 1 || prior.actor.length > 200
      || ![prior.rows_removed, prior.objects_rewritten, prior.objects_deleted].every(n => Number.isSafeInteger(n) && n >= 0)
      || (prior.done_through !== undefined && (typeof prior.done_through !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(prior.done_through)
        || !Number.isFinite(Date.parse(prior.done_through)) || dayOf(Date.parse(prior.done_through)) !== prior.done_through))) throw new Error('Erasure state unavailable');
    if (now <= prior.erased_at) return { key, tombstone: prior };
  }
  const tombstone: Tombstone = {
    tenant, visitor_id: visitorId, erased_at: Math.max(now, prior?.erased_at ?? 0), actor,
    rows_removed: prior?.rows_removed ?? 0, objects_rewritten: prior?.objects_rewritten ?? 0, objects_deleted: prior?.objects_deleted ?? 0,
  };
  await r2.put(key, JSON.stringify(tombstone), { httpMetadata: { contentType: 'application/json' } });
  return { key, tombstone };
}

export interface RewriteResult {
  tenant: string;
  /** Pending tombstones at the start of the run. */
  tombstones: number;
  /** The days this run cleaned, newest first. */
  days: string[];
  objects_opened: number;
  objects_rewritten: number;
  objects_deleted: number;
  rows_removed: number;
  /** Tombstones whose window is complete: retired to the audit prefix with a hash, no visitor id. */
  retired: number;
  /** Tombstones still pending after the run. */
  remaining: number;
  /** The run stopped at its object cap with days left; the next run continues. */
  more: boolean;
}

/**
 * The scheduled rewrite. For every pending tombstone the days to clean are the
 * erasure day back through the retention window; a day is cleaned only once it
 * is over (the queue has drained it), newest first, contiguously, so
 * `done_through` is always the oldest day cleaned and a resumed run continues
 * from the day after it. All tombstones share one pass over a day.
 */
export async function rewriteErasures(r2: R2Erasable, tenant: string, opts: { now?: number; retentionDays?: number; maxObjects?: number } = {}): Promise<RewriteResult> {
  const now = opts.now ?? Date.now();
  const window = opts.retentionDays ?? DEFAULT_RETENTION_DAYS;
  const cap = opts.maxObjects ?? 5000;
  const today = dayOf(now);
  const tombs = await loadTombstones(r2, tenant);
  const result: RewriteResult = { tenant, tombstones: tombs.size, days: [], objects_opened: 0, objects_rewritten: 0, objects_deleted: 0, rows_removed: 0, retired: 0, remaining: tombs.size, more: false };
  if (!tombs.size) return result;

  const floorOf = (t: Tombstone) => dayOf(t.erased_at - window * DAY);
  const nextOf = (t: Tombstone) => (t.done_through ? prevDay(t.done_through) : dayOf(t.erased_at));
  /** The days a tombstone still needs, newest first; none if its window is done or its next day is not over yet. */
  const daysFor = (t: Tombstone): string[] => {
    const out: string[] = [];
    for (let d = nextOf(t); d >= floorOf(t) && d < today; d = prevDay(d)) out.push(d);
    return out;
  };
  const wanted = new Map<string, Tombstone[]>();
  for (const t of tombs.values()) for (const d of daysFor(t)) (wanted.get(d) ?? wanted.set(d, []).get(d)!).push(t);
  const days = [...wanted.keys()].sort().reverse();
  const touched = new Set<Tombstone>();

  for (const day of days) {
    if (result.objects_opened >= cap) { result.more = true; break; }
    const targets = wanted.get(day)!;
    const eraseAt = new Map(targets.map((t) => [t.visitor_id, t.erased_at] as const));
    for (const key of await listKeys(r2, `${tenant}/${day}/`)) {
      result.objects_opened++;
      const obj = await r2.get(key);
      if (!obj) continue;
      const kept: string[] = [];
      const removedBy = new Map<string, number>();
      for (const line of (await obj.text()).split('\n')) {
        if (!line) continue;
        let rec: { visitor_id?: unknown; ts?: unknown } | null = null;
        try { rec = JSON.parse(line) as { visitor_id?: unknown; ts?: unknown }; } catch { kept.push(line); continue; }
        const at = typeof rec?.visitor_id === 'string' ? eraseAt.get(rec.visitor_id) : undefined;
        if (at !== undefined && typeof rec?.ts === 'number' && rec.ts <= at) { removedBy.set(rec.visitor_id as string, (removedBy.get(rec.visitor_id as string) ?? 0) + 1); continue; }
        kept.push(line);
      }
      if (!removedBy.size) continue;
      const emptied = kept.length === 0;
      if (emptied) { await r2.delete(key); result.objects_deleted++; } else { await r2.put(key, kept.join('\n') + '\n'); result.objects_rewritten++; }
      for (const [visitor, n] of removedBy) {
        const t = tombs.get(visitor)!;
        t.rows_removed += n; result.rows_removed += n;
        if (emptied) t.objects_deleted++; else t.objects_rewritten++;
      }
    }
    for (const t of targets) { t.done_through = day; touched.add(t); }
    result.days.push(day);
  }

  for (const t of touched) {
    const key = tombstoneKey(tenant, t.visitor_id);
    if (t.done_through && t.done_through <= floorOf(t)) {
      const retired: RetiredTombstone = {
        tenant, visitor_hash: visitorHash(t.visitor_id), erased_at: t.erased_at, rewritten_at: now, window_days: window,
        rows_removed: t.rows_removed, objects_rewritten: t.objects_rewritten, objects_deleted: t.objects_deleted,
      };
      await r2.put(`${retiredPrefix(tenant)}${t.erased_at.toString(36)}-${retired.visitor_hash}.json`, JSON.stringify(retired), { httpMetadata: { contentType: 'application/json' } });
      await r2.delete(key);
      result.retired++; result.remaining--;
    } else {
      await r2.put(key, JSON.stringify(t), { httpMetadata: { contentType: 'application/json' } });
    }
  }
  return result;
}

/**
 * The ledger half of an erasure, in one call for the identity route to make:
 * the tombstone, so every reader hides the rows now and the rewrite removes
 * them; and the visitor's own ring of served decisions, emptied. The profile
 * and the long index live in the shopper's object, which the identity route
 * erases itself.
 */
export async function resetVisitorRing(env: Pick<Env, 'DECISION_RING'>, tenant: string, visitorId: string): Promise<'reset' | 'unbound' | 'failed'> {
  let ring: 'reset' | 'unbound' | 'failed' = 'unbound';
  const ns = env.DECISION_RING;
  if (ns) {
    try {
      const res = await ns.get(ns.idFromName(`${tenant}:${visitorId}`)).fetch('https://learn/reset', { method: 'POST' });
      const body = await res.json() as { ok?: unknown; reset?: unknown };
      ring = res.ok && body.ok === true && body.reset === true ? 'reset' : 'failed';
    } catch { ring = 'failed'; }
  }
  return ring;
}

export async function eraseVisitorLedger(env: Pick<Env, 'STORAGE' | 'DECISION_RING'>, tenant: string, visitorId: string, actor: string, now = Date.now()): Promise<{ ok: boolean; tombstone: { key: string; erased_at: number }; ring: 'reset' | 'unbound' | 'failed' }> {
  const { key, tombstone } = await writeTombstone(env.STORAGE as unknown as R2Erasable, tenant, visitorId, actor, now);
  const ring = await resetVisitorRing(env, tenant, visitorId);
  return { ok: ring !== 'failed', tombstone: { key, erased_at: tombstone.erased_at }, ring };
}

// src/ledger/consume.ts
// What the worker's queue handler calls for the ledger messages in a batch.
// Never throws: a message the writer cannot place is acknowledged and counted,
// because a poison message that retries forever would stall every ledger write
// behind it, and R2 never sees anything the consumer could not parse.

import type { Env } from '@/types/env';
import { expandLedgerMessage, writeBatches, type R2Like } from './writer';
import type { LedgerMessage } from './records';

export interface ConsumeResult { written: number; objects: number; skipped: number; ok: boolean; error?: string }

/**
 * Write every placeable message in `bodies` to R2. Returns ok:false only when
 * R2 itself failed, which is the one case the caller should retry the batch.
 */
export async function consumeLedger(env: Pick<Env, 'STORAGE'>, bodies: readonly unknown[], now = Date.now()): Promise<ConsumeResult> {
  const messages: LedgerMessage[] = [];
  let skipped = 0;
  for (const b of bodies) { const got = expandLedgerMessage(b); if (got.length) messages.push(...got); else skipped++; }
  if (messages.length === 0) return { written: 0, objects: 0, skipped, ok: true };
  const batchId = `${now.toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
  try {
    const written = await writeBatches(env.STORAGE as unknown as R2Like, messages, batchId);
    return { written: messages.length, objects: written.length, skipped, ok: true };
  } catch (e) {
    return { written: 0, objects: 0, skipped, ok: false, error: e instanceof Error ? e.message : String(e) };
  }
}

// src/ledger/writer.ts
// The consumer: messages in, batches out. Each batch is one R2 object under
// `{tenant}/{date}/{hour}/{stream}/`, and the object is NAMED by the id range it
// holds, `{minTs}-{maxTs}-{batch}.ndjson`. That name is the hour's manifest
// entry, written atomically with the batch, so two consumers draining the same
// hour never race on a shared manifest file. A point lookup lists the hour and
// opens the one or two objects whose range contains the id's time.
//
// R2 and Analytics Engine are two destinations, not one reading the other. This
// file writes R2; the producer wrote the points.

import { fromTs36, hourPrefix, parseId, ts36, type LedgerMessage, type LedgerWireMessage } from './records';
import type { DecisionRecord } from '@/content/types';
import type { OutcomeRecord } from './records';

export interface R2Like {
  put(key: string, body: string): Promise<unknown>;
  get(key: string): Promise<{ text(): Promise<string> } | null>;
  list(opts: { prefix: string; cursor?: string; limit?: number }): Promise<{ objects: Array<{ key: string }>; truncated: boolean; cursor?: string }>;
}

export interface WrittenBatch { key: string; count: number; stream: 'decision' | 'outcome'; prefix: string }

const streamOf = (m: LedgerMessage) => m.type;
const idOf = (m: LedgerMessage) => (m.type === 'decision' ? m.record.decision_id : m.record.outcome_id);

/** Is this a ledger message with a record we can place? Anything else is dropped, and counted by the caller. */
export function isLedgerMessage(body: unknown): body is LedgerMessage {
  if (!body || typeof body !== 'object') return false;
  const m = body as { kind?: unknown; type?: unknown; record?: unknown };
  if (m.kind !== 'ledger' || (m.type !== 'decision' && m.type !== 'outcome') || !m.record || typeof m.record !== 'object') return false;
  const id = idOf(m as LedgerMessage);
  return typeof id === 'string' && parseId(id) !== null;
}
/** A message carrying a whole decision set (doc 31), or a single record: either way, the records it holds, each placeable. */
export function expandLedgerMessage(body: unknown): LedgerMessage[] {
  if (isLedgerMessage(body)) return [body];
  if (!body || typeof body !== 'object') return [];
  const m = body as { kind?: unknown; type?: unknown; records?: unknown };
  if (m.kind !== 'ledger' || m.type !== 'decisions' || !Array.isArray(m.records)) return [];
  return (m.records as unknown[]).map((record) => ({ kind: 'ledger' as const, type: 'decision' as const, record: record as DecisionRecord })).filter((x) => isLedgerMessage(x));
}
export type { LedgerWireMessage };

/** Group messages by stream and hour, write one object per group, return what was written. */
export async function writeBatches(r2: R2Like, messages: readonly LedgerMessage[], batchId: string): Promise<WrittenBatch[]> {
  const groups = new Map<string, { prefix: string; stream: 'decision' | 'outcome'; rows: LedgerMessage[]; min: number; max: number }>();
  for (const m of messages) {
    const id = parseId(idOf(m));
    if (!id) continue;
    const prefix = hourPrefix(id.tenant, id.ts);
    const stream = streamOf(m);
    const k = `${prefix}/${stream}`;
    const g = groups.get(k) ?? { prefix, stream, rows: [], min: Infinity, max: -Infinity };
    g.rows.push(m); g.min = Math.min(g.min, id.ts); g.max = Math.max(g.max, id.ts);
    groups.set(k, g);
  }
  const written: WrittenBatch[] = [];
  for (const g of groups.values()) {
    const key = `${g.prefix}/${g.stream}/${ts36(g.min)}-${ts36(g.max)}-${batchId}.ndjson`;
    const body = g.rows.map((m) => JSON.stringify(m.record)).join('\n') + '\n';
    await r2.put(key, body);
    written.push({ key, count: g.rows.length, stream: g.stream, prefix: g.prefix });
  }
  return written;
}

/** The objects under an hour whose id range could contain `ts`. */
export async function candidateKeys(r2: R2Like, tenant: string, ts: number, stream: 'decision' | 'outcome'): Promise<string[]> {
  const prefix = `${hourPrefix(tenant, ts)}/${stream}/`;
  const out: string[] = [];
  let cursor: string | undefined;
  do {
    const page = await r2.list({ prefix, cursor, limit: 1000 });
    for (const o of page.objects) {
      const name = o.key.slice(prefix.length);
      const m = /^([0-9a-z]{9})-([0-9a-z]{9})-/.exec(name);
      if (!m) continue;
      if (fromTs36(m[1]!) <= ts && ts <= fromTs36(m[2]!)) out.push(o.key);
    }
    cursor = page.truncated ? page.cursor : undefined;
  } while (cursor);
  return out;
}

/** One decision or outcome by id: parse the id, list the hour, open the candidates. No index anywhere. */
export async function findById<T extends DecisionRecord | OutcomeRecord>(r2: R2Like, id: string, stream: 'decision' | 'outcome'): Promise<{ record: T; key: string } | null> {
  const parsed = parseId(id);
  if (!parsed) return null;
  const field = stream === 'decision' ? 'decision_id' : 'outcome_id';
  for (const key of await candidateKeys(r2, parsed.tenant, parsed.ts, stream)) {
    const obj = await r2.get(key);
    if (!obj) continue;
    for (const line of (await obj.text()).split('\n')) {
      if (!line) continue;
      try {
        const rec = JSON.parse(line) as Record<string, unknown>;
        if (rec[field] === id) return { record: rec as unknown as T, key };
      } catch { /* a bad line never hides the good ones */ }
    }
  }
  return null;
}

// src/ledger/erasure.test.ts
// CW28 (doc 22 §15): a tombstone hides a visitor's rows at once, the rewrite
// removes them from the batch objects newest day first over the retention
// window, retires the tombstone with a hash and no id, resumes past its cap,
// and never touches another visitor or a row from after the erasure.

import { describe, it, expect, vi } from 'vitest';
import { writeBatches } from './writer';
import { ts36, type LedgerMessage } from './records';
import { dayOf, eraseVisitorLedger, resetVisitorRing, hidden, loadTombstones, pendingPrefix, retiredPrefix, rewriteErasures, tombstoneKey, withoutErased, writeTombstone } from './erasure';
import type { DecisionRecord } from '@/content/types';

class FakeR2 {
  store = new Map<string, string>(); puts = 0; deletes = 0;
  async put(key: string, body: string) { this.puts++; this.store.set(key, body); }
  async get(key: string) { const b = this.store.get(key); return b === undefined ? null : { text: async () => b }; }
  async delete(key: string) { this.deletes++; this.store.delete(key); }
  async list(opts: { prefix: string }) { return { objects: [...this.store.keys()].filter((k) => k.startsWith(opts.prefix)).sort().map((key) => ({ key })), truncated: false }; }
  keys(prefix: string) { return [...this.store.keys()].filter((k) => k.startsWith(prefix)).sort(); }
  rows(prefix: string) { return this.keys(prefix).flatMap((k) => this.store.get(k)!.split('\n').filter(Boolean).map((l) => JSON.parse(l) as { visitor_id: string; ts: number })); }
}

const DAY = 86_400_000;
const D = Date.UTC(2026, 10, 27, 14, 0, 0);          // 2026-11-27 14:00, the erasure day
const dec = (visitor: string, ts: number, n = 0): LedgerMessage => ({
  kind: 'ledger', type: 'decision',
  record: { decision_id: `coach:${ts36(ts)}:${visitor}:home:hero:${n}`, tenant: 'coach', brand: 'coach', visitor_id: visitor, ts, page: 'home', slot: 'hero', item_id: 'a' } as unknown as DecisionRecord,
});
const out = (visitor: string, ts: number): LedgerMessage => ({
  kind: 'ledger', type: 'outcome',
  record: { outcome_id: `coach:${ts36(ts)}:${visitor}:click`, tenant: 'coach', brand: 'coach', visitor_id: visitor, ts, type: 'click', event: 'click', item_id: 'a', slot: 'hero', value: null, currency: null, margin: null, products: null, session_id: null, arm: null },
});

/**
 * Two days of ledger. Objects are per stream and hour, so: 11-26 14h decisions hold only v1 (will empty);
 * 11-26 15h decisions are mixed (rewritten) and its outcomes hold only v1 (will empty); 11-27 13h decisions
 * are mixed (rewritten); 11-27 14h holds v1's one row from after the erasure (untouched).
 */
async function seed(r2: FakeR2) {
  const before = D - DAY;
  await writeBatches(r2, [dec('v1', before + 1000), dec('v1', before + 2000, 1)], 'b1');
  await writeBatches(r2, [dec('v2', before + 3_600_000), dec('v1', before + 3_600_500, 1), out('v1', before + 3_601_000)], 'b2');
  await writeBatches(r2, [dec('v1', D - 60_000), dec('v2', D - 50_000), dec('v1', D + 60_000, 2)], 'b3');
}

describe('CW28 erasure across the ledger', () => {
  it('a tombstone hides the visitor\'s rows at or before the erasure, and nothing else', async () => {
    const r2 = new FakeR2();
    await writeTombstone(r2, 'coach', 'v1', 'privacy@coach', D);
    const tombs = await loadTombstones(r2, 'coach');
    expect(tombs.get('v1')?.erased_at).toBe(D);
    expect(hidden(tombs, { visitor_id: 'v1', ts: D })).toBe(true);
    expect(hidden(tombs, { visitor_id: 'v1', ts: D - 1 })).toBe(true);
    expect(hidden(tombs, { visitor_id: 'v1', ts: D + 1 })).toBe(false);
    expect(hidden(tombs, { visitor_id: 'v2', ts: D - 1 })).toBe(false);
    const rows = [{ visitor_id: 'v1', ts: D - 5 }, { visitor_id: 'v2', ts: D - 5 }, { visitor_id: 'v1', ts: D + 5 }];
    expect(withoutErased(rows, tombs).map((r) => `${r.visitor_id}@${r.ts - D}`)).toEqual(['v2@-5', 'v1@5']);
    // Refreshing keeps the later erasure time and the counts.
    await writeTombstone(r2, 'coach', 'v1', 'privacy@coach', D - 10);
    expect((await loadTombstones(r2, 'coach')).get('v1')?.erased_at).toBe(D);
  });

  it('the rewrite removes the rows from the objects, deletes an emptied object, keeps the other visitor and the rows after the erasure, and retires the tombstone with a hash', async () => {
    const r2 = new FakeR2();
    await seed(r2);
    await writeTombstone(r2, 'coach', 'v1', 'privacy@coach', D);
    const r = await rewriteErasures(r2, 'coach', { now: D + DAY, retentionDays: 3 });
    expect(r.tombstones).toBe(1);
    expect(r.days).toEqual(['2026-11-27', '2026-11-26', '2026-11-25', '2026-11-24']);
    expect(r.rows_removed).toBe(5);           // v1: two at 11-26 14h, a decision and an outcome at 15h, one before the erasure on 11-27
    expect(r.objects_deleted).toBe(2);        // the two objects that held only v1
    expect(r.objects_rewritten).toBe(2);      // the two mixed objects
    expect(r.retired).toBe(1); expect(r.remaining).toBe(0); expect(r.more).toBe(false);
    const left = r2.rows('coach/2026-11-2');
    expect(left.map((x) => `${x.visitor_id}@${Math.round((x.ts - D) / 1000)}`).sort()).toEqual(['v1@60', 'v2@-50', 'v2@-82800']);
    expect(r2.keys(pendingPrefix('coach'))).toEqual([]);
    const retired = r2.keys(retiredPrefix('coach'));
    expect(retired).toHaveLength(1);
    const audit = JSON.parse(r2.store.get(retired[0]!)!) as Record<string, unknown>;
    expect(audit.visitor_id).toBeUndefined();
    expect(audit).toMatchObject({ tenant: 'coach', erased_at: D, window_days: 3, rows_removed: 5, objects_rewritten: 2, objects_deleted: 2 });
    expect(typeof audit.visitor_hash).toBe('string');
    expect(String(audit.visitor_hash)).not.toContain('v1');
    // A second run has nothing to do.
    const again = await rewriteErasures(r2, 'coach', { now: D + DAY, retentionDays: 3 });
    expect(again.tombstones).toBe(0); expect(again.rows_removed).toBe(0);
  });

  it('stops at its object cap after a whole day, keeps hiding meanwhile, and the next run continues from the day after', async () => {
    const r2 = new FakeR2();
    await seed(r2);
    await writeTombstone(r2, 'coach', 'v1', 'privacy@coach', D);
    const first = await rewriteErasures(r2, 'coach', { now: D + DAY, retentionDays: 3, maxObjects: 1 });
    expect(first.days).toEqual(['2026-11-27']); expect(first.more).toBe(true); expect(first.retired).toBe(0); expect(first.remaining).toBe(1);
    const tombs = await loadTombstones(r2, 'coach');
    expect(tombs.get('v1')?.done_through).toBe('2026-11-27');
    expect(hidden(tombs, { visitor_id: 'v1', ts: D - DAY })).toBe(true);   // the 11-26 rows are still hidden by the readers
    expect(r2.rows('coach/2026-11-26').filter((x) => x.visitor_id === 'v1')).toHaveLength(4);
    const second = await rewriteErasures(r2, 'coach', { now: D + DAY, retentionDays: 3, maxObjects: 100 });
    expect(second.days).toEqual(['2026-11-26', '2026-11-25', '2026-11-24']);
    expect(second.rows_removed).toBe(4); expect(second.retired).toBe(1);
    expect(r2.rows('coach/2026-11-26').filter((x) => x.visitor_id === 'v1')).toHaveLength(0);
  });

  it('never cleans a day that is not over yet, so rows still in the queue are not missed', async () => {
    const r2 = new FakeR2();
    await seed(r2);
    await writeTombstone(r2, 'coach', 'v1', 'privacy@coach', D);
    const r = await rewriteErasures(r2, 'coach', { now: D + 3_600_000, retentionDays: 3 });   // same day, an hour later
    expect(r.days).toEqual([]); expect(r.rows_removed).toBe(0); expect(r.remaining).toBe(1);
    expect((await loadTombstones(r2, 'coach')).get('v1')?.done_through).toBeUndefined();
    expect(dayOf(D)).toBe('2026-11-27');
  });

  it('eraseVisitorLedger writes the tombstone and empties the visitor\'s ring', async () => {
    const r2 = new FakeR2();
    const calls: string[] = [];
    const ns = {
      idFromName: (n: string) => n,
      get: (id: string) => ({ fetch: async (url: string, init?: { method?: string }) => { calls.push(`${id} ${init?.method ?? 'GET'} ${new URL(url).pathname}`); return new Response('{"ok":true,"reset":true}', { status: 200 }); } }),
    } as unknown as DurableObjectNamespace;
    const res = await eraseVisitorLedger({ STORAGE: r2 as unknown as R2Bucket, DECISION_RING: ns }, 'coach', 'v1', 'privacy@coach', D);
    expect(res).toEqual({ ok: true, tombstone: { key: tombstoneKey('coach', 'v1'), erased_at: D }, ring: 'reset' });
    expect(calls).toEqual(['coach:v1 POST /reset']);
    expect(r2.store.has(tombstoneKey('coach', 'v1'))).toBe(true);
    const unbound = await eraseVisitorLedger({ STORAGE: r2 as unknown as R2Bucket }, 'coach', 'v3', 'privacy@coach', D);
    expect(unbound.ring).toBe('unbound');
  });

  it('preserves same/earlier-cutoff progress and actor; only a later erasure restarts the rewrite window', async () => {
    const r2 = new FakeR2(); await seed(r2); await writeTombstone(r2, 'coach', 'v1', 'original-actor', D);
    await rewriteErasures(r2, 'coach', { now: D + DAY, retentionDays: 3, maxObjects: 1 });
    const key = tombstoneKey('coach', 'v1'), before = r2.store.get(key), puts = r2.puts;
    for (const at of [D, D - 1]) await writeTombstone(r2, 'coach', 'v1', 'retry-actor', at);
    expect(r2.store.get(key)).toBe(before); expect(r2.puts).toBe(puts);
    const old = JSON.parse(before!); const later = await writeTombstone(r2, 'coach', 'v1', 'new-actor', D + 1);
    expect(later.tombstone).toMatchObject({ erased_at: D + 1, actor: 'new-actor', rows_removed: old.rows_removed });
    expect(later.tombstone).not.toHaveProperty('done_through');
  });

  it('fails closed on unreadable/corrupt prior tombstones and reports malformed/failed ring acknowledgments without restarting progress', async () => {
    const valid = { tenant: 'coach', visitor_id: 'v1', erased_at: D, actor: 'actor', rows_removed: 0, objects_rewritten: 0, objects_deleted: 0 };
    const malformed = [{ erased_at: -1 }, { erased_at: D + 0.5 }, { erased_at: Number.MAX_SAFE_INTEGER + 1 },
      { done_through: '9999-99-99' }, { done_through: '2025-02-29' }, { actor: '' }, { actor: 'x'.repeat(201) }];
    for (const value of ['null', '{}', 'not-json', JSON.stringify({ tenant: 'other', visitor_id: 'v1', erased_at: D }),
      ...malformed.map(change => JSON.stringify({ ...valid, ...change }))]) {
      const r2 = new FakeR2(); r2.store.set(tombstoneKey('coach', 'v1'), value);
      await expect(writeTombstone(r2, 'coach', 'v1', 'actor', D)).rejects.toThrow(); expect(r2.puts).toBe(0);
    }
    const r2 = new FakeR2(); const reader = vi.spyOn(r2, 'get').mockRejectedValueOnce(new Error('synthetic read failure'));
    await expect(writeTombstone(r2, 'coach', 'v1', 'actor', D)).rejects.toThrow(); expect(r2.puts).toBe(0); reader.mockRestore();
    await writeTombstone(r2, 'coach', 'v1', 'actor', D); const puts = r2.puts;
    for (const [body, status] of [[{ ok: true }, 200], [{ ok: false, reset: true }, 200], [{ ok: true, reset: true }, 503], [null, 200]] as const) {
      const ns = { idFromName: (n: string) => n, get: () => ({ fetch: async () => Response.json(body, { status }) }) } as unknown as DurableObjectNamespace;
      const failed = await eraseVisitorLedger({ STORAGE: r2 as unknown as R2Bucket, DECISION_RING: ns }, 'coach', 'v1', 'retry', D);
      expect(failed.ok).toBe(false); expect(failed.ring).toBe('failed'); expect(r2.puts).toBe(puts);
      expect(await resetVisitorRing({ DECISION_RING: ns }, 'coach', 'v1')).toBe('failed'); expect(r2.puts).toBe(puts);
    }
  });
});

// src/ledger/ledger.test.ts
// Phase 0: records go out after the response, land in R2 as range-named
// batches under the brand and hour, and come back by id with no index.

import { describe, it, expect } from 'vitest';
import { enqueueDecisions, enqueueOutcome, pointsForDecisions } from './enqueue';
import { consumeLedger } from './consume';
import { candidateKeys, expandLedgerMessage, findById, isLedgerMessage, writeBatches } from './writer';
import { hourPrefix, outcomeFromAction, parseId, rewardOf, ts36, type OutcomeRecord } from './records';
import { decideContent } from '@/content/decide';
import type { ContentPiece, DecisionRecord, SlotStrategy } from '@/content/types';

class FakeR2 {
  store = new Map<string, string>(); puts = 0;
  async put(key: string, body: string) { this.puts++; this.store.set(key, body); }
  async get(key: string) { const b = this.store.get(key); return b === undefined ? null : { text: async () => b }; }
  async list(opts: { prefix: string }) { return { objects: [...this.store.keys()].filter((k) => k.startsWith(opts.prefix)).sort().map((key) => ({ key })), truncated: false }; }
}
class FakeQueue { sent: unknown[] = []; async send(b: unknown) { this.sent.push(b); } async sendBatch(ms: Array<{ body: unknown }>) { for (const m of ms) this.sent.push(m.body); } }
class FakeAE { points: unknown[] = []; writeDataPoint(p: unknown) { this.points.push(p); } }

const T0 = Date.UTC(2026, 10, 27, 14, 5, 0);   // 2026-11-27 14:05 UTC
const piece = (id: string, tags: Record<string, string[]>, slots: string[]): ContentPiece =>
  ({ id, customerContentId: `cms-${id}`, type: 'editorial', title: id, tags, slotTypes: slots, lifecycle: { status: 'live' } });
const slots: SlotStrategy[] = [{ slot: 'hero', take: 1, weights: { line: 0.3 } }, { slot: 'story', take: 2, weights: { line: 0.3 } }];
const set = (visitorId: string, nowMs = T0) => decideContent({
  tenant: 'coach', brand: 'coach', page: 'home', visitorId, sessionId: 's', identityAnchor: 'visitor', nowMs,
  pieces: [piece('a', { line: ['Drover'] }, ['hero', 'story']), piece('b', { line: ['Tabby'] }, ['story']), piece('c', {}, ['story'])],
  slots, affinity: { dims: { line: { Drover: 0.7 } } }, cell: { channel: 'direct', visit_bucket: '1', region: 'US-NY', affinity: 'line:Drover' },
  arm: 'personalized', versions: { config: 1, lift: 0, prior: 0, policy: 0 }, configLabel: 'v1',
});

describe('ids and prefixes', () => {
  it('the id carries the brand and the time, and the hour prefix follows from it', () => {
    const r = set('v1').records[0]!;
    expect(parseId(r.decision_id)).toEqual({ tenant: 'coach', ts: T0 });
    expect(hourPrefix('coach', T0)).toBe('coach/2026-11-27/14');
    expect(ts36(T0)).toHaveLength(9);
    expect(parseId('garbage')).toBeNull();
  });

  it('knows which wire events are rewards, including the ones the SDK sends as custom', () => {
    expect(rewardOf({ type: 'add_to_cart', userId: 'v' })).toEqual({ type: 'add_to_bag', event: 'add_to_cart' });
    expect(rewardOf({ type: 'custom', userId: 'v', data: { event: 'purchase' } })).toEqual({ type: 'purchase', event: 'purchase' });
    expect(rewardOf({ type: 'custom', userId: 'v', data: { event: 'content_dwell' } })).toEqual({ type: 'dwell', event: 'content_dwell' });
    expect(rewardOf({ type: 'product_view', userId: 'v' })).toBeNull();
    expect(rewardOf({ type: 'custom', userId: 'v', data: { event: 'content_impression' } })).toBeNull();
    const o = outcomeFromAction({ type: 'custom', userId: 'v9', sessionId: 's9', timestamp: T0, data: { event: 'purchase', orderId: 'o1', value: 395, currency: 'USD' } }, 'coach', 'coach', 'personalized')!;
    expect(o).toMatchObject({ outcome_id: `coach:${ts36(T0)}:v9:purchase`, type: 'purchase', item_id: 'o1', value: 395, currency: 'USD', arm: 'personalized', session_id: 's9' });
  });
});

describe('producer', () => {
  it('enqueues one message per decision set and writes one point per record, never throwing', async () => {
    const q = new FakeQueue(), ae = new FakeAE();
    const s = set('v1');
    await enqueueDecisions({ EVENT_QUEUE: q as never, ANALYTICS: ae as never }, s.records);
    expect(q.sent).toHaveLength(1);
    expect(q.sent[0]).toMatchObject({ kind: 'ledger', type: 'decisions', records: [{ decision_id: s.records[0]!.decision_id }, { decision_id: s.records[1]!.decision_id }, { decision_id: s.records[2]!.decision_id }] });
    expect(ae.points).toHaveLength(3);
    expect((ae.points[0] as { blobs: string[] }).blobs.slice(0, 5)).toEqual(['decision', 'coach', 'coach', 'home', 'hero']);
    await enqueueOutcome({ EVENT_QUEUE: q as never, ANALYTICS: ae as never }, outcomeFromAction({ type: 'add_to_cart', userId: 'v1', timestamp: T0, data: { productId: 'p1' } }, 'coach'));
    expect(q.sent).toHaveLength(2);
    await expect(enqueueDecisions({ EVENT_QUEUE: undefined as never, ANALYTICS: undefined as never }, s.records)).resolves.toBeUndefined();
    pointsForDecisions(undefined, s.records);
  });
});

describe('consumer and lookup', () => {
  it('writes one range-named object per brand, hour and stream, and finds a record by id with no index', async () => {
    const r2 = new FakeR2();
    const a = set('v1', T0), b = set('v2', T0 + 60_000), c = set('v3', T0 + 3_600_000 * 2);   // two in one hour, one two hours later
    const outcome = outcomeFromAction({ type: 'add_to_cart', userId: 'v1', timestamp: T0 + 5_000, data: { productId: 'p1' } }, 'coach')!;
    const bodies = [
      ...a.records.map((record) => ({ kind: 'ledger', type: 'decision', record })),
      ...b.records.map((record) => ({ kind: 'ledger', type: 'decision', record })),
      ...c.records.map((record) => ({ kind: 'ledger', type: 'decision', record })),
      { kind: 'ledger', type: 'outcome', record: outcome },
      { kind: 'scene', productId: 'x' },            // not ours: skipped, never written
      { kind: 'ledger', type: 'decision', record: { decision_id: 'no-time-in-this-id' } },
      'garbage',
    ];
    const res = await consumeLedger({ STORAGE: r2 as never }, bodies, T0 + 10_000);
    expect(res).toMatchObject({ ok: true, written: 10, objects: 3, skipped: 3 });
    const keys = [...r2.store.keys()].sort();
    expect(keys.filter((k) => k.startsWith('coach/2026-11-27/14/decision/'))).toHaveLength(1);
    expect(keys.filter((k) => k.startsWith('coach/2026-11-27/16/decision/'))).toHaveLength(1);
    expect(keys.filter((k) => k.startsWith('coach/2026-11-27/14/outcome/'))).toHaveLength(1);
    const hourObj = keys.find((k) => k.startsWith('coach/2026-11-27/14/decision/'))!;
    expect(hourObj).toMatch(new RegExp(`/${ts36(T0)}-${ts36(T0 + 60_000)}-`));   // named by its id range
    expect(r2.store.get(hourObj)!.trim().split('\n')).toHaveLength(6);

    const target = b.records[2]!;
    expect(await candidateKeys(r2, 'coach', T0 + 60_000, 'decision')).toEqual([hourObj]);
    const found = await findById<DecisionRecord>(r2, target.decision_id, 'decision');
    expect(found?.key).toBe(hourObj);
    expect(found?.record).toEqual(target);
    const o = await findById<OutcomeRecord>(r2, outcome.outcome_id, 'outcome');
    expect(o?.record).toEqual(outcome);
    expect(await findById(r2, `coach:${ts36(T0 + 999_999_999)}:nobody:home:hero:0`, 'decision')).toBeNull();
    expect(isLedgerMessage({ kind: 'ledger', type: 'decision', record: { decision_id: 'x' } })).toBe(false);
  });

  it('an R2 failure is the one case that reports not ok, so the caller can retry the batch', async () => {
    const r2 = new FakeR2(); r2.put = async () => { throw new Error('R2 unavailable'); };
    const res = await consumeLedger({ STORAGE: r2 as never }, set('v1').records.map((record) => ({ kind: 'ledger', type: 'decision', record })));
    expect(res.ok).toBe(false); expect(res.error).toContain('R2');
    expect(await writeBatches(new FakeR2(), [], 'b')).toEqual([]);
  });
});

describe('one message per decision set (doc 31)', () => {
  it('the producer sends the set as one message and the consumer expands it into its records', async () => {
    const q = new FakeQueue(), ae = new FakeAE();
    const out = set('v-set');
    await enqueueDecisions({ EVENT_QUEUE: q as never, ANALYTICS: ae as never }, out.records);
    expect(q.sent).toHaveLength(1);
    const m = q.sent[0] as { kind: string; type: string; records: unknown[] };
    expect([m.kind, m.type, m.records.length]).toEqual(['ledger', 'decisions', out.records.length]);
    const expanded = expandLedgerMessage(m);
    expect(expanded.map((x) => x.type)).toEqual(out.records.map(() => 'decision'));
    expect(expandLedgerMessage({ kind: 'ledger', type: 'decisions', records: [{ nope: true }] })).toEqual([]);
    expect(expandLedgerMessage({ kind: 'ledger', type: 'outcome', record: outcomeFromAction({ type: 'content_click', userId: 'v', timestamp: 5, data: { contentId: 'a' } }, 'coach') })).toHaveLength(1);
    // The consumer writes the set's records as one object per hour and stream.
    const r2 = new FakeR2();
    const res = await consumeLedger({ STORAGE: r2 as never }, [m], 1);
    expect([res.written, res.objects, res.skipped, res.ok]).toEqual([out.records.length, 1, 0, true]);
  });
});
